import React, { useRef, useEffect, useState, useMemo } from "react";
import { motion, useAnimationFrame } from "framer-motion";

interface CircularGalleryProps {
  bend?: number;
  textColor?: string;
  borderRadius?: number;
  scrollEase?: number;
  fontUrl?: string;
  font?: string;
  scrollSpeed?: number;
  images?: string[];
  labels?: string[];
}

interface GalleryItem {
  img: string;
  label: string;
  index: number;
}

export default function CircularGallery({
  bend = 1,
  textColor = "#ffffff",
  borderRadius = 0.05,
  scrollEase = 0.05,
  fontUrl = "",
  font = "bold 30px Orbitron",
  scrollSpeed = 2,
  images = [],
  labels = [],
}: CircularGalleryProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [items, setItems] = useState<GalleryItem[]>([]);
  const [dimensions, setDimensions] = useState({ width: 0, height: 0 });
  const [loadedImages, setLoadedImages] = useState<HTMLImageElement[]>([]);
  const scrollY = useRef(0);
  const targetScrollY = useRef(0);
  const animationRef = useRef<number>();

  const galleryItems = useMemo(() => {
    const defaultImages = [
      "https://images.unsplash.com/photo-1530103862676-de8c9debad1d?w=800",
      "https://images.unsplash.com/photo-1519167758481-83f550bb49b3?w=800",
      "https://images.unsplash.com/photo-1478146896981-b80fe463b330?w=800",
      "https://images.unsplash.com/photo-1470229722913-7c0e2dbbafd3?w=800",
      "https://images.unsplash.com/photo-1513519245088-0e12902e5a38?w=800",
      "https://images.unsplash.com/photo-1529636798458-92182e662485?w=800",
      "https://images.unsplash.com/photo-1519225421980-715cb0215aed?w=800",
      "https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800",
    ];

    const defaultLabels = [
      "Round Table Covers",
      "Chair Covers",
      "Chair Cover Bows",
      "Ceiling Drapes",
      "Chandeliers",
      "Hangings & Decorations",
      "Floral Decoration",
      "Finish Fabrics",
    ];

    const imgs = images.length > 0 ? images : defaultImages;
    const lbls = labels.length > 0 ? labels : defaultLabels;

    return imgs.map((img, i) => ({
      img,
      label: lbls[i] || `Item ${i + 1}`,
      index: i,
    }));
  }, [images, labels]);

  useEffect(() => {
    setItems(galleryItems);

    const loadImages = async () => {
      const imgs: HTMLImageElement[] = [];
      for (const item of galleryItems) {
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.src = item.img;
        await new Promise<void>((resolve) => {
          img.onload = () => resolve();
          img.onerror = () => resolve();
        });
        imgs.push(img);
      }
      setLoadedImages(imgs);
    };
    loadImages();
  }, [galleryItems]);

  useEffect(() => {
    if (!canvasRef.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const resize = () => {
      const rect = canvas.parentElement?.getBoundingClientRect();
      if (rect) {
        const dpr = window.devicePixelRatio || 1;
        canvas.width = rect.width * dpr;
        canvas.height = rect.height * dpr;
        canvas.style.width = `${rect.width}px`;
        canvas.style.height = `${rect.height}px`;
        setDimensions({ width: canvas.width, height: canvas.height });
      }
    };

    resize();
    window.addEventListener("resize", resize);

    const handleWheel = (e: WheelEvent) => {
      e.preventDefault();
      targetScrollY.current += e.deltaY * scrollSpeed * 0.1;
    };

    const handleTouchStart = (e: TouchEvent) => {
      const touch = e.touches[0];
      (canvasRef.current as any).__touchStartY = touch.clientY;
    };

    const handleTouchMove = (e: TouchEvent) => {
      const touch = e.touches[0];
      const startY = (canvasRef.current as any).__touchStartY;
      if (startY !== undefined) {
        const delta = touch.clientY - startY;
        targetScrollY.current -= delta * scrollSpeed * 0.5;
        (canvasRef.current as any).__touchStartY = touch.clientY;
      }
    };

    canvas.addEventListener("wheel", handleWheel, { passive: false });
    canvas.addEventListener("touchstart", handleTouchStart, { passive: true });
    canvas.addEventListener("touchmove", handleTouchMove, { passive: false });

    return () => {
      window.removeEventListener("resize", resize);
      canvas.removeEventListener("wheel", handleWheel);
      canvas.removeEventListener("touchstart", handleTouchStart);
      canvas.removeEventListener("touchmove", handleTouchMove);
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
    };
  }, [scrollSpeed]);

  useAnimationFrame((_, delta) => {
    if (!canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    scrollY.current += (targetScrollY.current - scrollY.current) * scrollEase;

    const { width, height } = dimensions;
    if (!width || !height || loadedImages.length === 0) return;

    ctx.clearRect(0, 0, width, height);

    const centerX = width / 2;
    const centerY = height / 2;
    const radius = Math.min(width, height) * 0.35;
    const itemCount = items.length;
    const angleStep = (Math.PI * 2) / itemCount;

    const scrollOffset = (scrollY.current * 0.001) % (Math.PI * 2);

    items.forEach((item, i) => {
      const img = loadedImages[i];
      if (!img) return;

      const angle = i * angleStep + scrollOffset;
      const bentAngle = angle * bend;

      const x = centerX + Math.sin(bentAngle) * radius;
      const y = centerY - Math.cos(bentAngle) * radius;
      const z = Math.cos(bentAngle) * radius * 0.5;

      const scale = 0.5 + (z + radius * 0.5) / (radius * 1.5);
      const itemWidth = radius * 0.85 * scale;
      const itemHeight = itemWidth * 1.3;

      const alpha = 0.3 + 0.7 * scale;

      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.translate(x, y);
      ctx.rotate(bentAngle);

      const r = itemWidth * borderRadius;
      ctx.beginPath();
      ctx.moveTo(-itemWidth / 2 + r, -itemHeight / 2);
      ctx.lineTo(itemWidth / 2 - r, -itemHeight / 2);
      ctx.quadraticCurveTo(itemWidth / 2, -itemHeight / 2, itemWidth / 2, -itemHeight / 2 + r);
      ctx.lineTo(itemWidth / 2, itemHeight / 2 - r);
      ctx.quadraticCurveTo(itemWidth / 2, itemHeight / 2, itemWidth / 2 - r, itemHeight / 2);
      ctx.lineTo(-itemWidth / 2 + r, itemHeight / 2);
      ctx.quadraticCurveTo(-itemWidth / 2, itemHeight / 2, -itemWidth / 2, itemHeight / 2 - r);
      ctx.lineTo(-itemWidth / 2, -itemHeight / 2 + r);
      ctx.quadraticCurveTo(-itemWidth / 2, -itemHeight / 2, -itemWidth / 2 + r, -itemHeight / 2);
      ctx.closePath();
      ctx.clip();

      ctx.drawImage(img, -itemWidth / 2, -itemHeight / 2, itemWidth, itemHeight);

      ctx.restore();

      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.font = font.replace("Orbitron", "system-ui, sans-serif").replace("30px", `${Math.max(14, 18 * scale)}px`);
      ctx.fillStyle = textColor;
      ctx.textAlign = "center";
      ctx.textBaseline = "top";
      const textY = y + itemHeight / 2 + 10 * scale;
      ctx.fillText(item.label, x, textY);
      ctx.restore();
    });
  });

  return (
    <div style={{ width: "100%", height: "100%", position: "relative" }}>
      <canvas
        ref={canvasRef}
        style={{
          width: "100%",
          height: "100%",
          display: "block",
          touchAction: "none",
        }}
      />
    </div>
  );
}
